const fs = require('fs');
const buf = fs.readFileSync('/workspace/testbed/docs/customer_report.docx');

// Minimal ZIP parser - find word/document.xml
const zlib = require('zlib');

// Find local file headers (PK\\x03\\x04)
let offset = 0;
const files = [];
while (offset < buf.length - 4) {
  if (buf[offset] === 0x50 && buf[offset+1] === 0x4B && buf[offset+2] === 0x03 && buf[offset+3] === 0x04) {
    const compMethod = buf.readUInt16LE(offset + 8);
    const compSize = buf.readUInt32LE(offset + 18);
    const uncompSize = buf.readUInt32LE(offset + 22);
    const nameLen = buf.readUInt16LE(offset + 26);
    const extraLen = buf.readUInt16LE(offset + 28);
    const name = buf.toString('utf8', offset + 30, offset + 30 + nameLen);
    const dataStart = offset + 30 + nameLen + extraLen;
    const data = buf.slice(dataStart, dataStart + compSize);

    if (name === 'word/document.xml') {
      let xml;
      if (compMethod === 8) {
        xml = zlib.inflateRawSync(data).toString('utf8');
      } else {
        xml = data.toString('utf8');
      }
      // Extract text between <w:t> tags
      const matches = xml.match(/<w:t[^>]*>([^<]*)<\/w:t>/g) || [];
      const texts = matches.map(m => m.replace(/<[^>]+>/g, ''));

      // Split by paragraph markers
      const paragraphs = xml.split(/<\/w:p>/);
      for (const para of paragraphs) {
        const tMatches = para.match(/<w:t[^>]*>([^<]*)<\/w:t>/g) || [];
        const line = tMatches.map(m => m.replace(/<[^>]+>/g, '')).join('');
        if (line) console.log(line);
        else if (tMatches.length === 0 && para.includes('<w:p ')) console.log('');
      }
      break;
    }
    offset = dataStart + compSize;
  } else {
    offset++;
  }
}
